Lemma accessible_cfgmaker : forall m, ACONST m -> accessible m AVP_CFGMAKER 8.
Proof. intros m AC. apply (ACONST_img_accessible m _ _ AC). vm_compute. reflexivity. Qed.
Scheme kc__3 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma hz_B2 : forall (sp s0 gp tp rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2 s3 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (spa ff regb A : Z) (frmA frmB mk3 : list cell) (ioc16 j4 : list byte) (hint : word),
  s9 = Z_to_bv 64 ff -> s10 = Z_to_bv 64 2147450880 ->
  6848512 <= ff -> ff + 1024 <= 2^64 -> ff mod 8 = 0 -> aapp ff 1024 -> 0 <= regb < 2^64 -> 0 <= A < 2^64 ->
  rw_cells asegs m ff (frmA ++ [C8 (Z_to_bv 64 A); CB 16 ioc16] ++ frmB) -> Z.of_nat (cells_size frmA) = 128 -> Z.of_nat (cells_size frmB) = 872 ->
  frmA = [C8 (Z_to_bv 64 HZ_MAGIC); C8 (Z_to_bv 64 HZ_DESCR); C8 (Z_to_bv 64 P_AFUZZ_ENTRY); C8 (Z_to_bv 64 spa); C8 (Z_to_bv 64 AVP_CFGMAKER); C4 hint; CB 4 j4] ++ mk3 ->
  ro_cells asegs m AVP_CFGMAKER [C8 (Z_to_bv 64 P_A_CONFIG_MAKE)] ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (fun ms' => exists t0' t1' t2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      ms' = MS (mkR (Z_to_bv 64 P_HZ_RET_MAK) (Z_to_bv 64 spa) gp tp t0' t1' t2' s0 (Z_to_bv 64 spa) (Z_to_bv 64 (ff + 32)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 P_A_CONFIG_MAKE)
                    a3' a4' a5' a6' a7' s2 s3 (Z_to_bv 64 (ff + 128)) s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
               F (Z_to_bv 64 P_A_CONFIG_MAKE) fc None m' (seg_rom asegs)
      /\ munch [(ff + 136, ff + 144)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ rw_cells asegs m' ff (frmA ++ [C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 regb); CB 8 (skipn 8 ioc16)] ++ frmB))
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 s0 (Z_to_bv 64 spa) (Z_to_bv 64 regb) a1 a2 a3 a4 a5 a6 a7 s2 s3 (Z_to_bv 64 (ff + 128)) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
